76	/**
77	 * Admin table for managing players, invitations, and email verification.
78	 *
79	 * @param props - Component props.
80	 * @param props.players - Players to render in the table.
81	 * @param props.userEmails - Better Auth user emails to determine onboarding status.
82	 * @returns The rendered admin player list table.
83	 */
84	export const AdminPlayerList = ({
85	    players,
86	    userEmails,
87	    userIdByEmail,
88	    onAddPlayerInvite,
89	    onSendEmail,
90	}: Props) => {
91	    const router = useRouter();
92	    const userEmailSet = useMemo(
93	        () => new Set((userEmails ?? [])
94	            .map((email) => normalizeEmail(email)).filter((email) => email.length > 0)),
95	        [userEmails],
96	    );
97	    const [sortKey, setSortKey] = useState<SortKey>('id');
98	    const [sortDirection, setSortDirection] = useState<SortDirection>('asc');
99	    const [selectedIds, setSelectedIds] = useState<number[]>([]);
100	    const [filter, setFilter] = useState('');
101	    const [filterFinished, setFilterFinished] = useState<FinishedFilter>('all');
102	    const [filterAuth, setFilterAuth] = useState<AuthFilter>('all');
103	    const [filterEmailsVerified, setFilterEmailsVerified] = useState<EmailsVerifiedFilter>('all');
104	
105	    /**
106	     * Filters players by name and the active tri-state filters.
107	     *
108	     * @returns The filtered player list.
109	     */
110	    const filteredPlayers = useMemo(() => {
111	        if (!players) return [];
112	        const trimmedFilter = filter.trim().toLowerCase();
113	        return players.filter((player) => {
114	            if (trimmedFilter && !player.name?.toLowerCase().includes(trimmedFilter)) return false;
115	            if (filterFinished === 'finished' && !player.finished) return false;
116	            if (filterFinished === 'active' && player.finished) return false;
117	            const claimed = isOnboarded(player, userEmailSet);
118	            if (filterAuth === 'claimed' && !claimed) return false;
119	            if (filterAuth === 'invited' && claimed) return false;
120	            if (filterEmailsVerified !== 'all') {
121	                const hasExtraEmails = player.extraEmails.length > 0;
122	                const extraEmailsVerified = hasExtraEmails && player.extraEmails.every((email) => email.verified);
123	                if (filterEmailsVerified === 'verified' && !extraEmailsVerified) return false;
124	                if (filterEmailsVerified === 'unverified' && (!hasExtraEmails || extraEmailsVerified)) return false;
125	            }
126	            return true;
127	        });
128	    }, [players, filter, filterFinished, filterAuth, filterEmailsVerified, userEmailSet]);
129	
130	    /**
131	     * Applies sorting to the filtered players.
132	     *
133	     * @returns The sorted player list.
134	     */
135	    const sortedPlayers = useMemo(() => {
136	        const data = [...filteredPlayers];
137	        data.sort((a, b) => comparePlayers(a, b, sortKey, sortDirection, userEmailSet));
138	        return data;
139	    }, [filteredPlayers, sortKey, sortDirection, userEmailSet]);
140	
141	    if (!players) {
142	        return (
143	            <Text>Loading players...</Text>
144	        );
145	    }
146	
147	    if (players.length === 0) {
148	        return (
149	            <Text>No players found.</Text>
150	        );
151	    }
152	
153	    /**
154	     * Selects or clears all visible players.
155	     *
156	     * @param checked - Whether the select-all checkbox is checked.
157	     */
158	    const toggleSelectAll = (checked: boolean) => {
159	        setSelectedIds(checked ? filteredPlayers.map((player) => player.id) : []);
160	    };
161	
162	    /**
163	     * Toggles a single player row selection.
164	     *
165	     * @param playerId - The player ID to toggle.
166	     * @param checked - Whether the checkbox is checked.
167	     */
168	    const toggleSelectPlayer = (playerId: number, checked: boolean) => {
169	        setSelectedIds((prev) => (
170	            checked ?
171	                [...prev, playerId] :
172	                prev.filter((id) => id !== playerId)
173	        ));
174	    };
175	
176	    const allSelected = filteredPlayers.length > 0 && selectedIds.length === filteredPlayers.length;
177	    const someSelected = selectedIds.length > 0 && !allSelected;
178	    const hasSelection = selectedIds.length > 0;
179	    const selectedPlayers = players.filter((player) => selectedIds.includes(player.id));
180	
181	    /**
182	     * Returns the sort icon for the provided column key.
183	     *
184	     * @param key - Column sort key.
185	     * @returns The appropriate sort icon element.
186	     */
187	    const getSortIcon = (key: SortKey) => {
188	        if (key !== sortKey) return <IconSelector size={14} />;
189	        return sortDirection === 'asc' ? <IconChevronUp size={14} /> : <IconChevronDown size={14} />;
190	    };
191	
192	    /**
193	     * Renders a sortable header label with the current sort icon.
194	     *
195	     * @param label - Column display label.
196	     * @param key - Column sort key.
197	     * @returns A sortable header element.
198	     */
199	    const renderSortHeader = (label: string, key: SortKey) => (
200	        <UnstyledButton
201	            type="button"
202	            onClick={() => handleSort(key)}
203	            aria-label={`Sort by ${label}`}
204	        >
205	            <Group gap={6} wrap="nowrap">
206	                <Text span>{label}</Text>
207	                {getSortIcon(key)}
208	            </Group>
209	        </UnstyledButton>
210	    );
211	
212	    /**
213	     * Updates the sort state for the selected column.
214	     *
215	     * @param key - Column sort key.
216	     */
217	    const handleSort = (key: SortKey) => {
218	        if (key === sortKey) {
219	            setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'));
220	            return;
221	        }
222	        setSortKey(key);
223	        setSortDirection('asc');
224	    };
225	
226	    /**
227	     * Sends onboarding invites and extra email verifications for the selected
228	     * players. Not expected to called with an empty list since the button is
229	     * disabled, but will handle that case anyway.
230	     *
231	     * @param onboardPlayers - The players to onboard.
232	     * @returns A promise that resolves when onboarding emails are handled.
233	     */
234	    const handleOnboardPlayers = async (onboardPlayers: PlayerDataType[]) => {
235	        const id = notifications.show({
236	            loading: true,
237	            title: 'Onboarding players',
238	            message: 'Sending onboarding emails...',
239	            autoClose: false,
240	            withCloseButton: false,
241	        });
242	
243	        try {
244	            let inviteSent = 0;
245	            let inviteSkipped = 0;
246	            for (const player of onboardPlayers) {
247	                const email = getPreferredEmail(player);
248	                if (!email) {
249	                    inviteSkipped += 1;
250	                } else {
251	                    const inviteLink = await onAddPlayerInvite(player.id, email);
252	                    const html = buildInviteEmail(inviteLink);
253	                    const cc = 'footy@toastboy.co.uk';
254	                    await onSendEmail({
255	                        to: email,
256	                        cc,
257	                        subject: 'Welcome to Toastboy FC!',
258	                        html,
259	                    });
