261	                }
262	            }
263	
264	            notifications.update({
265	                id,
266	                color: 'teal',
267	                title: 'Onboarding sent',
268	                message: [
269	                    `Invites: ${inviteSent} sent`,
270	                    inviteSkipped ? `${inviteSkipped} skipped` : null,
271	                ].filter(Boolean).join('. ') + '.',
272	                loading: false,
273	                autoClose: config.notificationAutoClose,
274	            });
275	        } catch (err) {
276	            captureUnexpectedError(err, {
277	                layer: 'client',
278	                component: 'AdminPlayerList',
279	                action: 'sendOnboarding',
280	                route: '/footy/admin/players',
281	                extra: {
282	                    selectedCount: selectedIds.length,
283	                },
284	            });
285	            notifications.update({
286	                id,
287	                color: 'red',
288	                title: 'Error',
289	                message: toPublicMessage(err, 'Failed to onboard players.'),
290	                loading: false,
291	                autoClose: false,
292	                withCloseButton: true,
293	            });
294	        }
295	    };
296	
