304	        const userId = getUserIdForPlayer(player);
305	
306	        // The button should be disabled if there's no userId.
307	
308	        const id = notifications.show({
309	            loading: true,
310	            title: 'Starting impersonation',
311	            message: 'Switching session...',
312	            autoClose: false,
313	            withCloseButton: false,
314	        });
315	
316	        try {
317	            const response = await fetch('/api/auth/admin/impersonate-user', {
318	                method: 'POST',
319	                headers: { 'Content-Type': 'application/json' },
320	                body: JSON.stringify({ userId }),
321	            });
322	
323	            await assertOkResponse(response, {
324	                method: 'POST',
325	                fallbackMessage: 'Failed to impersonate user.',
326	            });
327	
328	            router.refresh();
329	            notifications.update({
